# ========== 方案 A：Nginx / 网关层统一处理（推荐多服务场景）==========
# 优点：业务代码无 CORS 逻辑、灰度/多语言后端统一；缺点：动态 Origin 白名单需 map

map $http_origin $cors_origin {
    default "";
    "~^https://(app|admin)\.example\.com$" $http_origin;
}

server {
    listen 443 ssl http2;
    server_name api.example.com;

    location /api/ {
        # 预检请求：直接在 Nginx 层短路返回，不打到上游
        if ($request_method = OPTIONS) {
            add_header Access-Control-Allow-Origin $cors_origin always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods "GET,POST,PUT,DELETE,PATCH,OPTIONS" always;
            add_header Access-Control-Allow-Headers "Content-Type,Authorization,X-Request-Id" always;
            add_header Access-Control-Max-Age 600 always;  # 10 分钟，避免改头时长时间命中旧缓存
            add_header Content-Length 0;
            add_header Content-Type text/plain;
            return 204;
        }

        # 真实请求：转发上游后再补 CORS 头
        add_header Access-Control-Allow-Origin $cors_origin always;
        add_header Access-Control-Allow-Credentials true always;
        add_header Vary Origin always;  # 避免 CDN 把 A 站的 CORS 响应缓存给 B 站

        proxy_pass http://upstream_api;
    }
}

